import { useContext, useRef, useState } from "react";
import {
  Button,
  Form,
  Input,
  notification,
} from "antd";

import { SecurityLayout } from "../../layouts/SecurityLayout/index";
import securityImg from "../../assets/security.jpg";

import AuthContext from "../../context/AuthContext";
import { AuthService } from "../../service/AuthService";

export function Login() {
  var md5 = require('md5');
  const [loading, setLoading] = useState(false);
  const auth = useContext(AuthContext);

  const usuario = useRef();
  const senha = useRef();

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: "bottomLeft",
    });
  };

  const handleLogin = (data) => {
    setLoading(true);

    const AuthServ = new AuthService();

    AuthServ.login(data.usuario, md5(data.senha)).then((res) => {
      if (res.status === 200 && res.data.token !== undefined) {
        localStorage.setItem("isAuthenticated", true);
        localStorage.setItem("token", res.data.token);

        setTimeout(() => {
          setLoading(false);
          window.location.href = "/";
        }, 1200);
      } else {
        setLoading(false);
        openNotificationWithIcon(
          "error",
          "Usuário e/ou senha incorretos.",
          null,
          2.2
        );
      }
    }).catch((error) => {
      setLoading(false);
      console.log(error);

      openNotificationWithIcon(
        "error",
        "Usuário e/ou senha incorretos.",
        null,
        2.2
      );
    });

  };

  return (
    <div>
      <SecurityLayout>
        <div
          style={{
            backgroundColor: "#020644",
            borderRadius: '8px',
            paddingTop: '5px',
            paddingBottom: '5px',
            paddingLeft: 'auto',
            marginBottom: '25px'
          }}
        >
          <div
            style={{
              backgroundColor: "#020644",
              marginLeft: "auto",
              marginRight: "auto",
              marginTop: "20px",
              width: "150px",
              height: "55px",
              backgroundSize: "auto",
              backgroundRepeat: "no-repeat",
              backgroundImage: `url("https://abcsinformatica.com.br/img/abcs_branco.png")`,
            }}
          />
        </div>
        <Form method="POST" onFinish={(data) => handleLogin(data)} layout="vertical">
          <Form.Item
            label="Usuário"
            name="usuario"
            rules={[
              {
                required: true,
                message: "Insira seu usuário.",
              },
            ]}
            style={{ width: "100%" }}
          >
            <Input ref={usuario} placeholder="Usuário" />
          </Form.Item>
          <Form.Item
            label="Senha"
            name="senha"
            rules={[
              {
                required: true,
                message: "Insira sua senha.",
              },
            ]}
            style={{ width: "100%" }}
          >
            <Input.Password ref={senha} placeholder="Senha" />
          </Form.Item>
          <Button
            loading={loading}
            type="link"
            htmlType="submit"
            block
            children="Entrar"
            style={{
              marginTop: "15px",
              backgroundColor: "#020644",
              color: "white",
            }}
          />
        </Form>
      </SecurityLayout>
    </div>
  );
}
