import { ApiService } from "..";

export class EstabelecimentoService extends ApiService {
    getEstabelecimentos() {
        return this.get('/estabelecimentos');
    }

    getEstabelecimento(codigo){
        return this.post('/estabelecimentos/get', {
            'codigo': codigo
        })
    }

    getEstabelecimentoMenuByUsuario(usuarioData){
        return this.get("/estabelecimentos/get/"+usuarioData+"/usuario")
    }

    getEstabelecimentoRotas(){
        return this.get('/estabelecimentos/rotas');
    }

    create(estabData){
        return this.post('/estabelecimentos/create', {
            'nome': estabData.nome,
            'usuario': estabData.usuario,
            'token': estabData.token
        });
    }

    update(estabData) {
        return this.post('/estabelecimentos/update', {
            'codigo': estabData.codigo,
            'nome': estabData.nome,
            'usuario': estabData.usuario,
            'token': estabData.token
        });
    }

    delete(codigo) {
        return this.post('/estabelecimentos/delete', {
            'codigo': codigo
        });
    }
}