import { Result } from "antd";
import { Button } from "../../components/Button";

export const Page404 = () => {
    return (
        <div style={{ backgroundColor: '#020644', minHeight: '100vh' }}>
            <Result
                style={{ paddingTop: '100px' }}
                status="404"
                title={<div style={{ color: 'white' }}>Veio com muita fome e não achou nada? Não conseguimos encontrar essa página =(</div>}
                extra={<a href="https://abcsinformatica.com.br"><Button type="primary" children="ABCS Informática" /></a>}
            />
        </div>
    );
}