import { Navigate } from "react-router-dom";
import { Landing, Clientes, Estabelecimentos, EditarDados, CadastroCliente, CadastroEstabelecimento, EditarEstabelecimento, Page404, EditarCliente, Login, HorarioFuncionamentoCadastro, RelatorioCargas } from "../pages/index";

export const AuthenticatedRoutes = [
    {
        path: '/',
        element: <Landing />
    },
    {
        path: '/admin/clientes',
        element: <Clientes />
    },
    {
        path: '/admin/clientes/cadastro',
        element: <CadastroCliente />
    },
    {
        path: '/admin/cliente/:clienteCod/edit',
        element: <EditarCliente />
    },
    {
        path: '/admin/estabelecimentos',
        element: <Estabelecimentos />
    },
    {
        path: '/admin/estabelecimentos/cadastro',
        element: <CadastroEstabelecimento />
    },
    {
        path: '/admin/estabelecimento/:estabCod/cadastro/horario/funcionamento',
        element: <HorarioFuncionamentoCadastro />
    },
    {
        path: '/admin/estabelecimento/:estabCod/edit',
        element: <EditarEstabelecimento />
    },
    {
        path: '/relatorio/cargas',
        element: <RelatorioCargas />
    },
    {
        path: '/login',
        element: <Navigate replace to="/" />
    },
    {
        path: '*',
        element: <Page404 />
    }
];

export const NotAutheticatedRoutes = [
    {
        path: '/login',
        element: <Login />
    },
    {
        path: '/',
        element: <Navigate replace to="/login" />
    },
    {
        path: '*',
        element: <Page404 />
    }
];