import { Image, Typography } from "antd";

const { Title } = Typography;

export const CardapioHeader = ({ estabNome }) => {
    return (
        <div
            style={{
                backgroundColor: "#020650",
                height: "240px",
                width: "100%",
                marginTop: "-2px",
            }}
        >
            <div
                style={{
                    display: "flex",
                    justifyContent: "center",
                    paddingTop: "25px",
                }}
            >
                <Image
                    preview={false}
                    width={150}
                    src="https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png"
                />
            </div>
            <Title
                level={4}
                style={{
                    color: "white",
                    display: "flex",
                    justifyContent: "center",
                    paddingTop: "15px",
                }}
            >
                {estabNome}
            </Title>
        </div>
    );
}