import { Spin } from "antd";
import { useEffect, useState } from "react";
import { Routes as Switch, Route } from "react-router-dom";
import { Cardapio } from "../pages";
import { EstabelecimentoService } from "../service/EstabelecimentoService";
import { AuthenticatedRoutes, NotAutheticatedRoutes } from "./utils";

let routes = [];

if (localStorage.getItem('isAuthenticated') === 'true' && localStorage.getItem('token') !== null) {
  routes = AuthenticatedRoutes;
} else {
  routes = NotAutheticatedRoutes;
}

export function Routes() {
  const estabelecimentoServ = new EstabelecimentoService();
  const [routeLoadFinished, setRouteLoadFinished] = useState(false);

  const getEstabRotas = async () => {

    const res = await estabelecimentoServ.getEstabelecimentoRotas();
    const estabData = res.data.data;

    estabData.forEach(usuario => {
      routes.push({
        path: '/cardapio/' + usuario,
        element: <Cardapio estabUsuario={usuario} />
      });
    });

    setRouteLoadFinished(true);
  }

  getEstabRotas();

  useEffect(() => {
    console.log(routes);
  }, []);

  const routeComponents = routes.map(({ path, element }, key) => <Route exact path={path} element={element} key={`route-${key}`} />);

  if (routeLoadFinished) {
    return (
      <Switch>
        {routeComponents}
      </Switch>
    );
  } else {
    return (
      <div style={{ marginTop: "15%", display: "flex", justifyContent: "center" }}>
        <Spin tip="Carregando..." />
      </div>
    );
  }
}
