import { Button as ButtonAntD } from "antd";

export const Button = ({ htmlType, icon, loading, onClick, type, style, children }) => {
  return (
    <ButtonAntD
      type={type}
      icon={icon}
      style={{ borderRadius: '5px', ...style}}
      onClick={onClick}
      loading={loading}
      htmlType={htmlType}
    >
      {children}
    </ButtonAntD>
  );
};
