import { Button } from "antd";

import { PlusOutlined, MinusOutlined } from "@ant-design/icons";
import { useEffect, useState } from "react";

export const QtyButtons = ({ buttonsDisabled, btnClicked, produto, cart }) => {
  const [qtdRecheio, setQtdRecheio] = useState(
    cart ? cart.getTotalItemCarrinho(produto.CODIGO) : 0
  );
  const [minusBtnDisabled, setMinusBtnDisabled] = useState(cart ? cart.getTotalItemCarrinho(produto.CODIGO) === 0 : true);
  
  return (
    <div style={{ display: "inline-flex" }}>
      <Button
        type="primary"
        shape="circle"
        disabled={minusBtnDisabled}
        onClick={() => {
          qtdRecheio - 1 == 0 && setMinusBtnDisabled(true);
          setQtdRecheio(qtdRecheio - 1);
          btnClicked('sub', produto.CODIGO);
        }}
        icon={<MinusOutlined />}
      />
      <div
        style={{
          margin: "5px",
          fontSize: "1.18em",
        }}
      >
        {qtdRecheio}
      </div>
      
      <Button
        type="primary"
        shape="circle"
        disabled={buttonsDisabled}
        onClick={() => {
          qtdRecheio + 1 > 0 && setMinusBtnDisabled(false);
          setQtdRecheio(qtdRecheio + 1);
          btnClicked('add', produto);
        }}
        icon={<PlusOutlined />}
      />
    </div>
  );
};
