import { useEffect, useState } from "react";

import { AppLayout } from "../../../layouts/AppLayout";
import { Button, Card, Col, Form, Input, notification, Row } from "antd";
import { ClienteService } from "../../../service/ClienteService";
import { useNavigate, useParams } from "react-router-dom";
import { MaskedInput } from "antd-mask-input";

export const EditarCliente = () => {
    const [loadingSubmit, setLoadingSubmit] = useState(false);
    const navigate = useNavigate();
    const [formCliente] = Form.useForm();
    const params = useParams(); 

    const getClienteData = (codigo) => {
        const clienteServ = new ClienteService();

        clienteServ.getCliente(codigo).then((res) => {
            const cliente = res.data.data;
            formCliente.setFieldsValue({
                "codigo": cliente.CODIGO,
                "nome": cliente.NOME,
                "telefone": cliente.TELEFONE,
                "endereco": cliente.ENDERECO
            });
        }).catch((error) => {
            console.log(error);
        });   
    };

    useEffect(() => {
        getClienteData(params.clienteCod);
    }, []);

    const openNotificationWithIcon = (type, title, desc, timer) => {
        notification[type]({
            message: title,
            description: desc,
            duration: timer,
            placement: "bottomLeft",
        });
    };

    const submitEditCliente = (data) => {
        setLoadingSubmit(true);

        const clienteServ = new ClienteService();

        clienteServ.update(data).then((res) => {
            setLoadingSubmit(false);

            if (res.status === 200) {
                navigate("/admin/clientes", { replace: true });

                openNotificationWithIcon(
                    "success",
                    "Cadastro de cliente atualizado com sucesso.",
                    null,
                    2.2
                );
            }
        }).catch((err) => {
            setLoadingSubmit(false);
            openNotificationWithIcon(
                "error",
                "Erro ao atualizar cadastro de cliente.",
                null,
                2.2
            );
        });
    };

    return (
        <AppLayout activePage="clientes">
            <Row gutter={24}>
                <Card style={{ width: "100%" }} title="Editar Cliente">
                    <Form
                        form={formCliente}
                        onFinish={(data) => submitEditCliente(data)}
                        layout="vertical"
                    >
                        <Form.Item hidden name="codigo">
                            <Input />
                        </Form.Item>
                        <Row gutter={24}>
                            <Col span={6}>
                                <Form.Item label="Nome">
                                    <Form.Item
                                        name="nome"
                                        rules={[
                                            {
                                                required: true,
                                                message: "Insira o nome.",
                                            },
                                        ]}
                                    >
                                        <Input placeholder="Nome" />
                                    </Form.Item>
                                </Form.Item>
                            </Col>
                            <Col span={6}>
                                <Form.Item label="Telefone">
                                    <Form.Item
                                        name="telefone"
                                        rules={[
                                            {
                                                required: true,
                                                message: "Insira o telefone.",
                                            },
                                        ]}
                                    >
                                        <MaskedInput placeholder="Telefone" mask={'(00) 00000-0000'} />
                                    </Form.Item>
                                </Form.Item>
                            </Col>
                            <Col span={12}>
                                <Form.Item label="Endereço">
                                    <Form.Item
                                        name="endereco"
                                        rules={[
                                            {
                                                required: true,
                                                message: "Insira o endereço.",
                                            },
                                        ]}
                                    >
                                        <Input placeholder="Endereço" />
                                    </Form.Item>
                                </Form.Item>
                            </Col>
                            <Col span={24}>
                                <div style={{ display: "flex", justifyContent: "end" }}>
                                    <Button
                                        type="link"
                                        htmlType="submit"
                                        loading={loadingSubmit}
                                        style={{ backgroundColor: "#32a852", color: "white" }}
                                        children="Salvar"
                                    />
                                </div>
                            </Col>
                        </Row>
                    </Form>
                </Card>
            </Row>
        </AppLayout>
    );
};
