import { Form, Input } from "antd";
import { useEffect, useRef, useState } from "react";
import { EstabelecimentoService } from "../../../service/EstabelecimentoService";

export const UsernameInput = ({ formItemName, defaultValue }) => {
    const [validateUsernameStatus, setValidateUsernameStatus] = useState(null);
    const inputRef = useRef();
    const [help, setHelp] = useState(null);
    const [username, setUsername] = useState("");
    const [hasFeedback, setHasFeedback] = useState(false);
    const [lastCheckResult, setLastCheckResult] = useState(false);

    const checkUsernameInUseTimer = (_, value) => {
        if (!hasFeedback) {
            setHasFeedback(true);
            inputRef.current.focus({
                cursor: 'end',
            });
        }

        if (value === username) {
            if (lastCheckResult) {
                setValidateUsernameStatus("error");
                setHelp("Nome de usuário em uso.");
            } else {
                setValidateUsernameStatus("success");
                setHelp(null);
                return Promise.resolve();
            }
        } else {
            if (value !== "") {
                setValidateUsernameStatus("validating");
                setHelp(null);
                setUsername(value);
            }
        }
    }

    useEffect(() => {
        const checkUsernameInUse = () => {
            const estabelecimentoServ = new EstabelecimentoService();
            estabelecimentoServ.getEstabelecimentoRotas().then(res => {
                const estabUsernames = res.data.data;
                const checkResult = estabUsernames.filter(estabUsername => (defaultValue !== username && estabUsername === username)).length > 0;
                setLastCheckResult(checkResult);

                if (checkResult) {
                    setValidateUsernameStatus("error");
                    setHelp("Nome de usuário em uso.");
                } else {
                    setValidateUsernameStatus("success");
                    setHelp(null);
                }
            }).catch(err => {
                console.log(err);
            });
        }

        const timeOutId = setTimeout(() => checkUsernameInUse(), 1500);
        return () => clearTimeout(timeOutId);
    }, [username]);

    return (
        <Form.Item
            name={formItemName}
            extra="Esse será o endereço para acesso ao cardápio."
            hasFeedback={hasFeedback}
            validateStatus={validateUsernameStatus}
            help={help}
            rules={[
                {
                    required: true,
                    message: "Insira o nome de usuário do estabelecimento.",
                },
                {
                    validator: checkUsernameInUseTimer,
                },
                {
                    validator(_, value) {
                        var format = /[ `!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~]/;
                        if (!format.test(value)) {
                            return Promise.resolve();
                        } else {
                            return Promise.reject(new Error('O nome de usuário não pode conter espaços e/ou caracteres especiais.'));
                        }
                    },
                }
            ]}
        >
            <Input ref={inputRef} placeholder="Nome de Usuário" />
        </Form.Item>
    );
}