import { useContext, useEffect, useState } from "react";

import { AppLayout } from "../../layouts/AppLayout";

import {
  Card,
  notification,
  Row,
  Popconfirm,
  Space,
  Table,
} from "antd";

import { EditOutlined, DeleteOutlined } from "@ant-design/icons";

import ShoppingCartContext from "../../context/ShoppingCartContext";

import { ClienteService } from "../../service/ClienteService";
import { Link } from "react-router-dom";
import { Button } from "../../components/Button";

export const Clientes = () => {
  const [loading, setLoading] = useState(false);
  const [clientes, setClientes] = useState([]);
  const cart = useContext(ShoppingCartContext);

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: "bottomLeft",
    });
  };

  useEffect(() => {
    getClientes();
  }, []);

  const handleDelete = (codigo) => {
    const clienteServ = new ClienteService();

    clienteServ.delete(codigo).then((res) => {
      openNotificationWithIcon(
        "success",
        "Cliente excluído com sucesso.",
        null,
        2.2
      );

      getClientes();
    }).catch((error) => {
      openNotificationWithIcon(
        "error",
        "Houve um erro ao excluir o cliente.",
        null,
        2.2
      );
    });
  }

  const getClientes = () => {
    setLoading(true);

    const clienteServ = new ClienteService();

    clienteServ.getClientes().then((res) => {
      console.log(res);

      setLoading(false);
      setClientes(res.data.data);

      return res.data;
    }).catch((error) => {
      setLoading(false);
      console.log(error);
    });
  };

  const columns = [
    {
      title: "Nome",
      dataIndex: "NOME",
      key: "NOME",
    },
    {
      title: "Telefone",
      dataIndex: "TELEFONE",
      key: "TELEFONE",
    },
    {
      title: "Endereço",
      dataIndex: "ENDERECO",
      key: "ENDERECO",
    },
    {
      title: 'Ações',
      width: 20,
      key: 'action',
      render: (_, record) => (
        <Space size="middle">
          <Link to={"/admin/cliente/" + record.CODIGO + "/edit"}>
            <Button icon={<EditOutlined />} type="primary" />
          </Link>
          <Popconfirm
            title="Você tem certeza que deseja deletar esse registro?"
            onConfirm={() => handleDelete(record.CODIGO)}
            onCancel={() => {}}
            okText="Sim"
            cancelText="Não"
          >
            <Button icon={<DeleteOutlined />} type="danger" />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AppLayout activePage="clientes">
      <Row gutter={24}>
        <Card
          style={{ width: "100%" }}
          title="Clientes"
          extra={
            <Link
              to="/admin/clientes/cadastro"
              children={
                <Button
                  type="link"
                  style={{ backgroundColor: "#32a852", color: "white" }}
                >
                  + Novo
                </Button>
              }
            />
          }
        >
          <Table scroll={{ x: 'auto' }} loading={loading} columns={columns} dataSource={clientes} />
        </Card>
      </Row>
    </AppLayout>
  );
};
