import { Card, Row, Table } from "antd";
import { useEffect, useState } from "react";
import { AppLayout } from "../../../layouts/AppLayout";
import { CargaService } from "../../../service/CargaService";
import Moment from 'moment';

export const RelatorioCargas = () => {
    const [loading, setLoading] = useState();
    const [cargas, setCargas] = useState();

    const cargaServ = new CargaService();

    const columns = [
        {
            title: "Nome do Estabelecimento",
            dataIndex: "NOME",
            key: "NOME",
        },
        {
            title: "Token",
            dataIndex: "TOKEN",
            key: "TOKEN",
        },
        {
            title: "Data de Carga",
            dataIndex: "DATACARGA",
            key: "DATACARGA",
            render: (data) => {
                return Moment(data).format("DD/MM/YYYY HH:mm:ss");
            }
        },
    ]

    useEffect(() => {
        const getCargas = () => {
            setLoading(true);

            cargaServ.getHistoricoCarga().then(res => {
                setTimeout(() => {
                    setLoading(false);
                }, 1500);
                setCargas(res.data.data);
            }).catch(err => {
                setLoading(false);
                console.log(err);
            });
        }

        getCargas();
        const interval = setInterval(() => {
            getCargas();
        }, 30000);
        return () => clearInterval(interval);
    }, []);

    return (
        <AppLayout activePage="cargas">
            <Row gutter={24}>
                <Card style={{ width: '100%' }} title="Relatório de Cargas">
                    <Table scroll={{ x: 'auto' }} loading={loading} dataSource={cargas} columns={columns} />
                </Card>
            </Row>
        </AppLayout>
    );
}