import { notification } from "antd";
import axios from "axios";

// API LOCAL
// const BASE_URL = 'http://localhost:8000/api';

// API TESTE
const BASE_URL = 'https://restaurante.abcsinformatica.com.br/api';

let defaultHeaders = {};

if(localStorage.getItem("token") != null){
    defaultHeaders = {
        Authorization: `${localStorage.getItem("token")}`
    };
}

const defaultOptions = {
    baseURL: BASE_URL,
    headers: defaultHeaders
};

const axiosCon = axios.create(defaultOptions);

axiosCon.interceptors.response.use(response => {
    return response;
 }, error => {
    console.log(error);
   if (error.response.status === 401) {
    localStorage.setItem("isAuthenticated", false);
    localStorage.removeItem("token");

    window.location.href = '/login';
    notification.error({
        message: "Token inválido",
        duration: 3
    });
   }
   return error;
 });

export class ApiService {
    get(path) {
        return axiosCon.get(path);
    }

    post(path, data) {
        return axiosCon.post(path, data);
    }

    put(path) {
        return axiosCon.put(path);
    }

    patch(path) {
        return axiosCon.patch(path);
    }

    delete(path) {
        return axiosCon.delete(path);
    }
}