import React, { useContext, useEffect, useState } from "react";

import { CardapioLayout } from "../../layouts/CardapioLayout";

import { Card, Typography, List, Row, Tabs } from "antd";
import { CardapioHeader } from "../../components/cardapio/header";
import { EstabelecimentoService } from "../../service/EstabelecimentoService";
import { QtyButtons } from "../../components/qtyButtons";
import ShoppingCartContext from "../../context/ShoppingCartContext";

const { TabPane } = Tabs;
const { Title } = Typography;

export const Cardapio = ({ estabUsuario }) => {
  const [loading, setLoading] = useState(true);
  const cart = useContext(ShoppingCartContext);
  const [estab, setEstab] = useState({});
  const [produtos, setProdutos] = useState({});
  const [gruposProd, setGruposProd] = useState({});

  const getEstab = () => {
    setLoading(true);

    const estabServ = new EstabelecimentoService();

    estabServ.getEstabelecimentoMenuByUsuario(estabUsuario).then((res) => {
      const data = res.data.data;
      setEstab(data.estab);
      setProdutos(data.produtos);
      setGruposProd(data.grupos_prod);

      setLoading(false);
    }).catch((error) => {
      setLoading(false);
    });
  };

  const addToCart = (btnClick, produto) => {
    if (btnClick === 'add') {
      cart.adicionarItem(produto.CODIGO, produto.NOME, "", 50);
    } else {
      cart.removerItem(produto.CODIGO);
    }
  }

  useEffect(() => {
    getEstab();
  }, []);

  return (
    <CardapioLayout activePage="clientes">
      <CardapioHeader estabNome={estab.NOME} />
      <Card
        style={{
          width: "80vw",
          marginLeft: "auto",
          marginRight: "auto",
          border: "none",
        }}
      >
        {!loading && (
          <>
            {gruposProd.length > 0 && produtos.length > 0 ? (
              <>
                <Tabs
                  tabPosition="top"
                  style={{
                    height: '350',
                  }}
                >
                  {gruposProd.map((grupo) => {
                    return (
                      <TabPane tab={grupo.DESCRICAO} key={"tab-" + grupo.CODIGO}>
                        <List
                          itemLayout="horizontal"
                          size="large"
                          pagination={{
                            onChange: (page) => {
                              console.log(page);
                            },
                            pageSize: 3,
                          }}
                        >
                          {produtos.filter(item => item.CODGRUPO === grupo.CODIGO).map(item => {
                            return (
                              <List.Item
                                style={{ width: '100%' }}
                                key={item.CODIGO}
                                actions={[
                                  <QtyButtons btnClicked={addToCart} produto={item} cart={cart} />
                                ]}
                              >
                                <List.Item.Meta
                                  title={item.NOME}
                                />
                              </List.Item>
                            )
                          })}
                        </List>
                      </TabPane>
                    );
                  })}
                </Tabs>
              </>
            ) : (
              <Title level={5} style={{ textAlign: 'center' }}>Cardápio indisponível</Title>
            )}
          </>
        )}
      </Card>
    </CardapioLayout>
  );
};
