import { useEffect, useState } from "react";

import { AppLayout } from "../../../layouts/AppLayout";
import { Button, Card, Col, Form, Input, notification, Row } from "antd";
import { ClienteService } from "../../../service/ClienteService";
import { useNavigate } from "react-router-dom";
import { MaskedInput } from "antd-mask-input";

export const CadastroCliente = () => {
  const [loadingSubmit, setLoadingSubmit] = useState(false);
  const navigate = useNavigate();
  const [formCliente] = Form.useForm();

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: "bottomLeft",
    });
  };

  const submitCliente = (data) => {
    setLoadingSubmit(true);

    const clienteServ = new ClienteService();

    clienteServ.create(data).then((res) => {
      setLoadingSubmit(false);

      if (res.status === 200) {
        navigate("/admin/clientes", { replace: true });

        openNotificationWithIcon(
          "success",
          "Cliente cadastrado com sucesso.",
          null,
          2.2
        );
      }
    }).catch((err) => {
      setLoadingSubmit(false);
      openNotificationWithIcon(
        "error",
        "Erro ao cadastrar cliente.",
        null,
        2.2
      );
    });
  };

  return (
    <AppLayout activePage="clientes">
      <Row gutter={24}>
        <Card style={{ width: "100%" }} title="Cadastro de Clientes">
          <Form
            form={formCliente} 
            onFinish={(data) => submitCliente(data)} 
            layout="vertical"
          >
            <Row gutter={24}>
              <Col span={6}>
                <Form.Item label="Nome">
                  <Form.Item
                    name="nome"
                    rules={[
                      {
                        required: true,
                        message: "Insira o nome.",
                      },
                    ]}
                  >
                    <Input placeholder="Nome" />
                  </Form.Item>
                </Form.Item>
              </Col>
              <Col span={6}>
                <Form.Item label="Telefone">
                  <Form.Item
                    name="telefone"
                    rules={[
                      {
                        required: true,
                        message: "Insira o telefone.",
                      },
                    ]}
                  >
                    <MaskedInput placeholder="Telefone" mask={'(00) 00000-0000'} />
                  </Form.Item>
                </Form.Item>
              </Col>
              <Col span={12}>
                <Form.Item label="Endereço">
                  <Form.Item
                    name="endereco"
                    rules={[
                      {
                        required: true,
                        message: "Insira o endereço.",
                      },
                    ]}
                  >
                    <Input placeholder="Endereço" />
                  </Form.Item>
                </Form.Item>
              </Col>
              <Col span={24}>
                <div style={{ display: "flex", justifyContent: "end" }}>
                  <Button
                    type="link"
                    htmlType="submit"
                    loading={loadingSubmit}
                    style={{ backgroundColor: "#32a852", color: "white" }}
                    children="Salvar"
                  />
                </div>
              </Col>
            </Row>
          </Form>
        </Card>
      </Row>
    </AppLayout>
  );
};
