import { createContext, useState } from "react";
import { notification } from "antd";

const DEFAULT_STATE = {
  state: {
    items: [],
  },
  setState: () => {},
};

const ShoppingCartContext = createContext(DEFAULT_STATE);

const ShoppingCartContextProvider = ({ children }) => {
  const [state, setState] = useState(DEFAULT_STATE.state);

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: 'bottomLeft'
    });
  };

  const adicionarItem = (itemId, itemNome, itemDesc, itemValor) => {
    let cartItems = state.items;
    let item = cartItems.find(i => i.id == itemId);

    if (item != null) {
      cartItems.splice(cartItems.indexOf(item), 1);
      
      item = {
        ...item,
        qtd: item.qtd + 1
      }

      cartItems = [
        ...cartItems,
        item
      ]
    } else {
      cartItems = [
        ...cartItems,
        {
          id: itemId,
          nome: itemNome,
          descricao: itemDesc,
          valor: itemValor,
          qtd: 1
        },
      ];
    }

    setState({
      ...state,
      items: cartItems,
    });

    openNotificationWithIcon(
      "success",
      "Item adicionado ao carrinho com sucesso!",
      null,
      1.4
    );
  };

  const removerItem = (itemId) => {
    let cartItems = state.items;

    cartItems.splice(cartItems.findIndex(item => item.id == itemId), 1);

    setState({
      ...state,
      items: cartItems,
    });
    
    openNotificationWithIcon(
      "success",
      "Item removido do carrinho com sucesso!",
      null,
      1.4
    );
  };

  const getTotalItensCarrinho = () => {
    const cartItems = state.items;
    let qtdTotal = 0;

    cartItems.map(item => {
      qtdTotal += item.qtd
    });

    return qtdTotal;
  }

  const getTotalItemCarrinho = (id) => {
    const cartItems = state.items;
    let qtdTotal = 0;

    cartItems.map(item => {
      qtdTotal += item.id == id && item.qtd;
    });

    return qtdTotal;
  }

  return (
    <ShoppingCartContext.Provider
      value={{
        state,
        setState,
        getTotalItensCarrinho,
        getTotalItemCarrinho,
        adicionarItem,
        removerItem,
      }}
    >
      {children}
    </ShoppingCartContext.Provider>
  );
};

export { ShoppingCartContextProvider };
export default ShoppingCartContext;
