import { useEffect, useState } from "react";

import uuid from "react-uuid";

import { AppLayout } from "../../../layouts/AppLayout";

import { Card, Col, Collapse, Form, Input, notification, Row } from "antd";

import { Button } from "../../../components/Button";

import { EstabelecimentoService } from '../../../service/EstabelecimentoService/index'
import { Link, useParams } from "react-router-dom";
import { UsernameInput } from "../../../components/estabelecimento/usernameInput";

const { Panel } = Collapse;

export const EditarEstabelecimento = () => {
    const [loadingSubmit, setLoadingSubmit] = useState(false);
    const [defaultValueCodigo, setDefaultValueCodigo] = useState(null);
    const [defaultValueUsuario, setDefaultValueUsuario] = useState(null);
    const [formEstab] = Form.useForm();
    const params = useParams();

    const openNotificationWithIcon = (type, title, desc, timer) => {
        notification[type]({
            message: title,
            description: desc,
            duration: timer,
            placement: "bottomLeft",
        });
    };

    const getEstabData = () => {
        const estabServ = new EstabelecimentoService();

        estabServ.getEstabelecimento(params.estabCod).then((res) => {
            const estab = res.data.data;
            setDefaultValueUsuario(estab.USUARIO);
            setDefaultValueCodigo(estab.CODIGO);
            formEstab.setFieldsValue({
                "codigo": estab.CODIGO,
                "nome": estab.NOME,
                "usuario": estab.USUARIO,
                "token": estab.TOKEN
            });
        }).catch((error) => {

        });
    }

    const submitEditEstabelecimento = (data) => {
        setLoadingSubmit(true);

        const estabServ = new EstabelecimentoService();

        estabServ.update(data).then((res) => {
            setLoadingSubmit(false);

            if (res.status === 200) {
                window.location.href = '/admin/estabelecimentos';

                openNotificationWithIcon(
                    "success",
                    "Cadastro de estabelecimento atualizado com sucesso.",
                    null,
                    2.2
                );
            }
        }).catch((err) => {
            setLoadingSubmit(false);
            openNotificationWithIcon(
                "error",
                "Erro ao atualizar cadastro de estabelecimento.",
                null,
                2.2
            );
        });
    };

    const generateToken = () => {
        let uuidToken = uuid().toString();

        formEstab.setFieldsValue({
            token: uuidToken,
        });
    };

    useEffect(() => {
        getEstabData();
    }, []);

    return (
        <AppLayout activePage="estabelecimentos">
            <Row gutter={24}>
                <Card style={{ width: "100%" }} title="Editar Estabelecimento">
                    <Form form={formEstab} onFinish={(data) => submitEditEstabelecimento(data)} layout="vertical">
                        <Form.Item hidden name="codigo">
                            <Input />
                        </Form.Item>
                        <Row gutter={24}>
                            <Col span={12}>
                                <Form.Item label="Nome do Estabelecimento">
                                    <Form.Item
                                        name="nome"
                                        rules={[
                                            {
                                                required: true,
                                                message: "Insira o nome do estabelecimento.",
                                            },
                                        ]}
                                    >
                                        <Input placeholder="Nome do Estabelecimento" />
                                    </Form.Item>
                                </Form.Item>
                            </Col>
                            <Col span={12}>
                                <Form.Item label="Nome de Usuário">
                                    <UsernameInput formItemName="usuario" defaultValue={defaultValueUsuario} />
                                </Form.Item>
                            </Col>
                            <Col span={12}>
                                <Form.Item
                                    label="Token"
                                    extra="Esse será o token de acesso ao sistema."
                                >
                                    <Row gutter={8}>
                                        <Col span={16}>
                                            <Form.Item
                                                name="token"
                                                noStyle
                                                rules={[
                                                    {
                                                        required: true,
                                                        message: "Preencha esse campo com um token.",
                                                    },
                                                ]}
                                            >
                                                <Input placeholder="Token" readOnly />
                                            </Form.Item>
                                        </Col>
                                        <Col span={6}>
                                            <Button
                                                type="link"
                                                style={{ backgroundColor: "#111496", color: "white" }}
                                                onClick={() => generateToken()}
                                            >
                                                Gerar Token
                                            </Button>
                                        </Col>
                                    </Row>
                                </Form.Item>
                            </Col>
                            <Col span={24}>
                                <Form.Item
                                    extra="Caso não adicione um horário de funcionamento, 
                                    o estabelecimento estará sempre aberto."
                                >
                                    <Link
                                        to={"/admin/estabelecimento/" + defaultValueCodigo + "/cadastro/horario/funcionamento"}
                                        children={
                                            <Button 
                                                type='primary' 
                                                style={{ backgroundColor: "#111496", color: "white" }}
                                                children="Cadastrar Horário de Funcionamento" 
                                            />
                                        }
                                    />
                                </Form.Item>
                            </Col>
                            <Col span={24}>
                                <div style={{ marginTop: '25px', display: "flex", justifyContent: "end" }}>
                                    <Button
                                        type="link"
                                        htmlType="submit"
                                        loading={loadingSubmit}
                                        style={{ backgroundColor: "#32a852", color: "white" }}
                                        children="Salvar"
                                    />
                                </div>
                            </Col>
                        </Row>
                    </Form>
                </Card>
            </Row>
        </AppLayout>
    );
};