import { useContext, useState } from "react";
import { Layout, Menu, Spin, Modal, Drawer, Row, Col, List, Popconfirm, Badge, Avatar, Form, Input } from "antd";
import { Link, useLocation } from "react-router-dom";
import ShoppingCartContext from "../../context/ShoppingCartContext";
import { Button } from '../../components/Button';

import { DeleteOutlined, ShoppingCartOutlined } from '@ant-design/icons';

const { Header, Sider, Content, Footer } = Layout;
const { SubMenu } = Menu;

export function CardapioLayout({ children }) {
  const cart = useContext(ShoppingCartContext)
  const location = useLocation();
  const [loadingLogout, setLoadingLogout] = useState();
  const [modalEnterVisible, setModalEnterVisible] = useState(false);
  const [cartVisible, setCartVisible] = useState(false);

  const handleEnter = () => {

  }

  return (
    <>
      <Modal
        title="Entrar"
        visible={modalEnterVisible}
        footer={null}
        onCancel={() => setModalEnterVisible(false)}
        width={400}
      >
        <Form
          style={{
            paddingRight: '15px',
            paddingLeft: '15px',
          }}
          size="middle"
          onFinish={(data) => handleEnter(data.telefone)} 
          layout="vertical"
        >
          <Form.Item label="Número de Telefone" name="telefone">
            <Input placeholder="Número de Telefone" />
          </Form.Item>
          <div  style={{ display: 'flex', justifyContent: 'end', paddingTop: '6px', paddingBottom: '5px' }}>
            <Button
              style={{
                backgroundColor: '#020650',
                color: 'white',
                width: '100%'
              }}
              htmlType="submit"
              children="Entrar"
            />
          </div>
        </Form>
      </Modal>
      {loadingLogout && (
        <div
          style={{
            position: "absolute",
            zIndex: 999999,
            display: "flex",
            top: "50%",
            left: "50%",
          }}
        >
          <Spin size="large" />
        </div>
      )}

      <Layout>
        <Menu theme="dark" mode="horizontal" style={{ height: '40px' }}>
          <div style={{ marginRight: 'auto', pointerEvents: 'none' }}>
            <Menu.Item>ABCS Delivery</Menu.Item>
          </div>
          <Menu.Item
            onClick={() => setModalEnterVisible(true)}
          >
            Entrar
          </Menu.Item>
          <Menu.Item
            icon={
              <Badge
                count={cart.getTotalItensCarrinho()}
                showZero={true}
                size="small"
              >
                <ShoppingCartOutlined style={{ color: 'white' }} />
              </Badge>
            }
            onClick={() => setCartVisible(true)}
          >
            Carrinho
          </Menu.Item>
          <Menu.Item
            onClick={() => setModalEnterVisible(true)}
          >
            Sair
          </Menu.Item>
        </Menu>
        <Layout
          style={{
            backgroundColor: "white",
          }}
        >
          <Content
            style={{
              minHeight: "70vh",
            }}
          >
            <Drawer
              title="Seu Carrinho"
              placement="right"
              closable={true}
              visible={cartVisible}
              onClose={() => setCartVisible(false)}
              extra={
                <Button
                  type="primary"
                  children="Fazer pedido"
                  disabled={cart.getTotalItensCarrinho() == 0}
                  style={{ backgroundColor: "#597ef7" }}
                />
              }
            >
              <Row gutter={24}>
                <Col span={24}>
                  <List
                    locale={{ emptyText: "Seu carrinho está vazio." }}
                    itemLayout="horizontal"
                    dataSource={cart.state.items}
                    renderItem={(item) => (
                      <List.Item
                        actions={[
                          <Popconfirm
                            title="Você tem certeza que quer deletar esse pedido?"
                            onConfirm={() => {
                              cart.removerItem(item.id);
                            }}
                            okText="Sim"
                            cancelText="Não"
                          >
                            <DeleteOutlined />
                          </Popconfirm>,
                        ]}
                      >
                        <List.Item.Meta
                          avatar={
                            <Badge count={item.qtd} size="small">
                              <Avatar
                                size={64}
                                src="https://blog.ceraflame.com.br/wp-content/uploads/2021/06/Pizza-Napolitana-CERAFLAME.jpg"
                              />
                            </Badge>
                          }
                          title={item.nome}
                          description={item.descricao}
                        />
                      </List.Item>
                    )}
                  />
                </Col>
              </Row>
            </Drawer>
            {children}
          </Content>
          <Footer
            style={{
              display: "flex",
              justifyContent: "center",
              marginTop: "138px",
              bottom: 0
            }}
          >
            Essa é uma solução de &nbsp;
            <a target="_blank" href="https://abcsinformatica.com.br/">
              ABCS Informática
            </a>
          </Footer>
        </Layout>
      </Layout>
    </>
  );
}
