import { ApiService } from "..";

export class ClienteService extends ApiService {
    getClientes() {
        return this.get('/clientes');
    }

    getCliente(codigo) {
        return this.post('/clientes/get', {
            'codigo': codigo
        });
    }

    create(clienteData){
        return this.post('/clientes/create', {
            'nome': clienteData.nome,
            'endereco': clienteData.endereco,
            'telefone': clienteData.telefone
        });

    }

    update(clienteData) {
        return this.post('/clientes/update', {
            'codigo': clienteData.codigo,
            'nome': clienteData.nome,
            'endereco': clienteData.endereco,
            'telefone': clienteData.telefone
        });
    }

    delete(codigo) {
        return this.post('/clientes/delete', {
            'codigo': codigo
        });
    }
}