import { useContext, useEffect, useState } from "react";

import {
  Avatar,
  Badge,
  Col,
  Drawer,
  Layout,
  List,
  Popconfirm,
  Row,
  Menu,
  Button,
  notification,
  message,
  Spin,
  Alert,
} from "antd";
// import { Menu } from "../../components/menu";

import {
  IdcardOutlined,
  DeleteOutlined,
  TeamOutlined,
  ShopOutlined,
  HomeOutlined,
  LogoutOutlined,
  FileTextOutlined,
  CloudUploadOutlined,
} from "@ant-design/icons";

import "./AppLayout.css";

import { Link, useLocation } from "react-router-dom";
import ShoppingCartContext from "../../context/ShoppingCartContext";
import AuthContext from "../../context/AuthContext";

const { Header, Sider, Content, Footer } = Layout;

const { SubMenu } = Menu;

export function AppLayout({ children, activePage }) {
  const location = useLocation();

  const [loadingLogout, setLoadingLogout] = useState();

  const { pathname } = location;

  const pathnameSplitStr = pathname.split("/");

  const adminSubMenuItems = ["clientes", "estabelecimentos"];
  const reportsSubMenuItems = ["cargas"];

  const checkOpenKeys = () => {
    if (adminSubMenuItems.includes(pathnameSplitStr[2])) {
      return ["admin"];
    } else if (reportsSubMenuItems.includes(pathnameSplitStr[2])) {
      return ["reports"];
    } else {
      return [];
    }
  };

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: "bottomLeft",
    });
  };

  const [drawerVisibility, setDrawerVisibility] = useState(false);
  const [logoVisible, setLogoVisible] = useState(false);
  const [openKeys, setOpenKeys] = useState(checkOpenKeys());

  const cart = useContext(ShoppingCartContext);
  const auth = useContext(AuthContext);

  const handleLogout = () => {
    setLoadingLogout(true);

    if (auth.logout()) {
      openNotificationWithIcon(
        "success",
        "Você foi deslogado com sucesso!",
        null,
        2.2
      );

      window.location.href = "/login";

      setLoadingLogout(false);
    } else {
      openNotificationWithIcon(
        "error",
        "Não foi possível sair do sistema, por favor tente novamente em alguns instantes.",
        null,
        2.2
      );

      setLoadingLogout(false);
    }
  };

  return (
    <>
      {loadingLogout && (
        <div
          style={{
            position: "absolute",
            zIndex: 999999,
            display: "flex",
            top: "50%",
            left: "50%",
          }}
        >
          <Spin size="large" />
        </div>
      )}

      <Layout style={{ minHeight: '100vh' }}>
        <Sider
          style={{ backgroundColor: "#020644" }}
          breakpoint="lg"
          onBreakpoint={broken => {
            setLogoVisible(!broken);
          }}
        >
          {logoVisible && (
            <Link
              to="/"
              children={
                <div
                  style={{
                    zIndex: 99999,
                    marginLeft: "20px",
                    marginTop: "20px",
                    width: "150px",
                    height: "55px",
                    backgroundSize: "auto",
                    backgroundRepeat: "no-repeat",
                    backgroundImage: `url("https://abcsinformatica.com.br/img/abcs_branco.png")`,
                  }}
                />
              }
            />
          )}

          <Menu
            mode="inline"
            theme="dark"
            defaultSelectedKeys={["/"]}
            defaultOpenKeys={openKeys}
            selectedKeys={[pathnameSplitStr[2]]}
            onClick={(itemCLicked) => {
              setOpenKeys([itemCLicked.keyPath[1]]);
            }}
          >
            {!logoVisible && (
              <Menu.Item key="" icon={<HomeOutlined />}>
                <Link to="/" children="Home" />
              </Menu.Item>
            )}

            <SubMenu
              key="admin"
              title="Administração"
              icon={<IdcardOutlined />}
            >
              <Menu.Item key="clientes" icon={<TeamOutlined />}>
                <Link to="/admin/clientes" children="Clientes" />
              </Menu.Item>
              <Menu.Item key="estabelecimentos" icon={<ShopOutlined />}>
                <Link to="/admin/estabelecimentos" children="Estabelecimentos" />
              </Menu.Item>
            </SubMenu>

            <SubMenu
              key="reports"
              title="Relatórios"
              icon={<FileTextOutlined />}
            >
              <Menu.Item key="cargas" icon={<CloudUploadOutlined />}>
                <Link to="/relatorio/cargas" children="Cargas" />
              </Menu.Item>
            </SubMenu>

            <Menu.Item
              style={{
                position: "absolute",
                bottom: 0,
                zIndex: 1,
                transition: "all 0.2s",
              }}
              icon={<LogoutOutlined />}
              onClick={handleLogout}
              key="logout"
            >
              Sair
            </Menu.Item>
          </Menu>
        </Sider>
        <Layout>
          <Content style={{ padding: "35px", minHeight: "70vh" }}>
            {children}
            <Drawer
              title="Seu Carrinho"
              placement="right"
              closable={true}
              visible={drawerVisibility}
              onClose={() => setDrawerVisibility(false)}
              extra={
                <Button
                  type="primary"
                  children="Fazer pedido"
                  disabled={cart.getTotalItensCarrinho() == 0}
                  style={{ backgroundColor: "#597ef7" }}
                />
              }
            >
              <Row gutter={24}>
                <Col span={24}>
                  <List
                    locale={{ emptyText: "Seu carrinho está vazio." }}
                    itemLayout="horizontal"
                    dataSource={cart.state.items}
                    renderItem={(item) => (
                      <List.Item
                        actions={[
                          <Popconfirm
                            title="Você tem certeza que quer deletar esse pedido?"
                            onConfirm={() => {
                              cart.removerItem(item.id);
                            }}
                            okText="Sim"
                            cancelText="Não"
                          >
                            <DeleteOutlined />
                          </Popconfirm>,
                        ]}
                      >
                        <List.Item.Meta
                          avatar={
                            <Badge count={item.qtd} size="small">
                              <Avatar
                                size={64}
                                src="https://blog.ceraflame.com.br/wp-content/uploads/2021/06/Pizza-Napolitana-CERAFLAME.jpg"
                              />
                            </Badge>
                          }
                          title={item.nome}
                          description={item.descricao}
                        />
                      </List.Item>
                    )}
                  />
                </Col>
              </Row>
            </Drawer>
          </Content>
          <Footer
            style={{
              display: "flex",
              justifyContent: "center",
              marginTop: "138px",
            }}
          >
            Essa é uma solução de &nbsp;
            <a target="_blank" href="https://abcsinformatica.com.br/">
              ABCS Informática
            </a>
          </Footer>
        </Layout>
      </Layout>
    </>
  );
}
