import { useEffect, useState } from "react";

import { AppLayout } from "../../layouts/AppLayout";
import {
  Card,
  notification,
  Popconfirm,
  Row,
  Space,
  Table,
} from "antd";

import {
  EditOutlined,
  DeleteOutlined,
  EyeOutlined
} from "@ant-design/icons";

import { EstabelecimentoService } from "../../service/EstabelecimentoService";
import { Link } from "react-router-dom";
import { Button } from "../../components/Button";

export const Estabelecimentos = () => {
  const [loading, setLoading] = useState(false);
  const [estabelecimentos, setEstabelecimentos] = useState([]);

  const openNotificationWithIcon = (type, title, desc, timer) => {
    notification[type]({
      message: title,
      description: desc,
      duration: timer,
      placement: "bottomLeft",
    });
  };

  useEffect(() => {
    getEstabelecimentos();
  }, []);

  const handleDelete = (codigo) => {
    const estabServ = new EstabelecimentoService();
    estabServ.delete(codigo).then((res) => {
      openNotificationWithIcon(
        "success",
        "Estabelecimento deletado com sucesso.",
        null,
        2.2
      );
      getEstabelecimentos();
    }).catch((err) => {
      openNotificationWithIcon(
        "error",
        "Houve um erro ao excluir o estabelecimento.",
        null,
        2.2
      );
      getEstabelecimentos();
    });
  }

  const getEstabelecimentos = () => {
    setLoading(true);

    const estabelecimentoServ = new EstabelecimentoService();

    estabelecimentoServ.getEstabelecimentos().then((res) => {
      console.log(res);

      setLoading(false);
      setEstabelecimentos(res.data.data);

      return res.data;
    }).catch((error) => {
      setLoading(false);

      console.log(error);
    });
  };

  const columns = [
    {
      title: "Nome",
      dataIndex: "NOME",
      key: "NOME",
    },
    {
      title: "Usuário",
      dataIndex: "USUARIO",
      key: "USUARIO",
    },
    {
      title: "Token",
      dataIndex: "TOKEN",
      key: "TOKEN",
    },
    {
      title: 'Ações',
      width: 20,
      key: 'action',
      render: (_, record) => (
        <Space size="middle">
          <Link to={`/cardapio/${record.USUARIO}`}>
            <Button icon={<EyeOutlined />} type="default" children="Ver Cardápio"/>
          </Link>
          <Link to={"/admin/estabelecimento/" + record.CODIGO + "/edit"}>
            <Button icon={<EditOutlined />} type="primary"/>
          </Link>
          <Popconfirm
            title="Você tem certeza que deseja deletar esse registro?"
            onConfirm={() => handleDelete(record.CODIGO)}
            onCancel={() => {}}
            okText="Sim"
            cancelText="Não"
          >
            <Button icon={<DeleteOutlined />} type="danger"/>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AppLayout activePage="estabelecimentos">
      <Row gutter={24}>
        <Card
          style={{ width: "100%" }}
          title="Estabelecimentos"
          extra={
            <Link
              to="/admin/estabelecimentos/cadastro"
              children={
                <Button
                  type="link"
                  style={{ backgroundColor: "#32a852", color: "white" }}
                >
                  + Novo
                </Button>
              }
            />
          }
        >
          <Table scroll={{ x: 'auto' }} loading={loading} columns={columns} dataSource={estabelecimentos} />
        </Card>
      </Row>
    </AppLayout>
  );
};
