import { useEffect, useState } from "react";
import { AppLayout } from "../../layouts/AppLayout/index";
import { DashboardService } from "../../service/DashboardService";

import { Card, Col, Row, Statistic } from "antd";
import {
  TeamOutlined,
  ShopOutlined,
  CloudUploadOutlined
} from '@ant-design/icons'

export function Landing() {
  const dashboardService = new DashboardService();
  const [loading, setLoading] = useState(false);
  const [dashInfo, setDashInfo] = useState({
    "qtdClientes": 0,
    "qtdEstabelecimentos": 0,
    "qtdCargas": 0,
  });

  useEffect(() => {
    const getDashInfo = () => {
      setLoading(true);
      dashboardService.getDashboardInfo().then(res => {
        const data = res.data.data;
        setDashInfo(data);
        setTimeout(() => {
          setLoading(false);
        }, 1500);
      }).catch(err => {
        setLoading(false);
        console.log(err);
      });
    }    
    
    getDashInfo();
    const interval = setInterval(() => {
      getDashInfo();
    }, 20000);
    return () => clearInterval(interval);
  }, []);

  return (
    <>
      <AppLayout activePage='home'>
        <Row gutter={24}>
          <Col xs={24} sm={12} md={6} xl={4}>
            <Statistic
              loading={loading}
              style={{ backgroundColor: 'white', padding: '20px' }}
              title="Clientes"
              value={dashInfo.qtdClientes}
              valueStyle={{ color: '#3f8600' }}
              prefix={<TeamOutlined />}
            />
          </Col>
          <Col xs={24} sm={12} md={6} xl={4}>
            <Statistic
              loading={loading}
              style={{ backgroundColor: 'white', padding: '20px' }}
              title="Estabelecimentos"
              value={dashInfo.qtdEstabelecimentos}
              valueStyle={{ color: '#3f8600' }}
              prefix={<ShopOutlined />}
            />
          </Col>
          <Col xs={24} sm={12} md={6} xl={4}>
            <Statistic
              loading={loading}
              style={{ backgroundColor: 'white', padding: '20px' }}
              title="Cargas Realizadas"
              value={dashInfo.qtdCargas}
              valueStyle={{ color: '#3f8600' }}
              prefix={<CloudUploadOutlined />}
            />
          </Col>
        </Row>
      </AppLayout>
    </>
  );
}
